#!/usr/bin/env python3
"""Apply script: restore lost upload-UI improvements + Quick upload auto-detection.

Run from the HealthCross repo root: python3 apply_quick_upload_workflow.py
"""
import base64, hashlib, os, sys

MARKER = "QUICK_UPLOAD_WORKFLOW_2026_08_04"

FILES = [
    {
        'path': 'app/api/routes_cases.py',
        'sha256': '1f3a6a05aa9d6f54fea540d1c87ee5aa68138961ba08413a414a522c1fd9b03e',
        'size': 29416,
        'b64': '',
    },
    {
        'path': 'app/static/index.html',
        'sha256': '27a622259a3c6325d6c344e631cbc7f4b68ccbdf7256a1e2372d4cbdab24e3de',
        'size': 151302,
        'b64': '',
    },
    {
        'path': 'app/ingestion/upload_sniffer.py',
        'sha256': '50ff270d427ee9c4a3ff6b78d38814889ae9afe49d58767ff63122d4486368ea',
        'size': 5916,
        'b64': '',
    },
    {
        'path': 'tests/test_api_detect_upload_kind.py',
        'sha256': '3c4d8b9d3a29ca62904a88c3de87d3b3635c0a823eee0ca8f632a80a8ed53839',
        'size': 1753,
        'b64': '',
    },
    {
        'path': 'tests/test_ingestion_upload_sniffer.py',
        'sha256': '1de83df8a82ecf306af3871b530eeaa2dbb14d04549cb24d360d94b247a02d10',
        'size': 5161,
        'b64': '',
    },
]


def main():
    repo_root = os.getcwd()
    ok = True
    for entry in FILES:
        path = os.path.join(repo_root, entry['path'])
        data = base64.b64decode(entry['b64'])
        if len(data) != entry['size']:
            print(f"SIZE MISMATCH before write: {entry['path']}")
            ok = False
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(data)
        with open(path, 'rb') as f:
            written = f.read()
        actual_sha = hashlib.sha256(written).hexdigest()
        if actual_sha == entry['sha256']:
            print(f"OK  {entry['path']}  ({len(written)} bytes, sha256={actual_sha[:12]}...)")
        else:
            print(f"CHECKSUM MISMATCH  {entry['path']}  expected={entry['sha256'][:12]}... actual={actual_sha[:12]}...")
            ok = False
    if ok:
        print(f"\nAll files written and verified. Marker: {MARKER}")
        print("Next: pip install -r requirements.txt   (adds python-calamine if missing)")
        print("Then: python3 -m pytest -q   (should show 470 passed)")
        print("Then: git add app/api/routes_cases.py app/static/index.html app/ingestion/upload_sniffer.py tests/test_api_detect_upload_kind.py tests/test_ingestion_upload_sniffer.py apply_quick_upload_workflow.py")
        print("      git commit -m 'Restore lost upload-UI improvements and add Quick upload auto-detection'")
        print("      git push")
    else:
        print("\nSOME FILES FAILED TO VERIFY - do not commit. Re-run this script once more first.")
        sys.exit(1)


if __name__ == '__main__':
    main()
